metadata.content:
Proceed with Phase 2B.6 — LuminaExecutiveRibbon.
The reusable boundary is the hero shell, ambient gradient, top reflection, inner padding, and vertical slot spacing. Knowledge keeps the identity, operations deck, metrics, and their ordering.
Bashcd /Users/erictouko/dev/korelumina

mkdir -p \
  apps/lumina-builder/src/components/design-system/lumina/executive/ribbon

cat > \
apps/lumina-builder/src/components/design-system/lumina/executive/ribbon/LuminaExecutiveRibbon.tsx <<'EOF'
import type {
  ReactNode,
} from "react";

import { cn } from "@/lib/utils";

export interface LuminaExecutiveRibbonProps {
  identity: ReactNode;
  operations: ReactNode;
  metrics: ReactNode;
  className?: string;
  contentClassName?: string;
}

export function LuminaExecutiveRibbon({
  identity,
  operations,
  metrics,
  className,
  contentClassName,
}: LuminaExecutiveRibbonProps) {
  return (
    <header
      className={cn(
        "group relative h-full min-w-0 overflow-hidden",
        "rounded-[30px]",
        "border border-white/[0.08]",
        "bg-[linear-gradient(145deg,rgba(15,23,42,.78),rgba(15,23,42,.58))]",
        "shadow-[0_28px_160px_rgba(0,0,0,.40)]",
        className,
      )}
    >
      <div
        aria-hidden="true"
        className={[
          "pointer-events-none absolute inset-0",
          "bg-[radial-gradient(circle_at_top_left,rgba(34,211,238,.10),transparent_36%),radial-gradient(circle_at_top_right,rgba(139,92,246,.11),transparent_40%),linear-gradient(180deg,rgba(255,255,255,.02),transparent_34%)]",
        ].join(" ")}
      />

      <div
        aria-hidden="true"
        className="pointer-events-none absolute inset-x-[7%] top-0 h-px bg-gradient-to-r from-transparent via-white/25 to-transparent"
      />

      <div
        className={cn(
          "relative z-10 flex h-full min-w-0 flex-col px-8 py-9",
          contentClassName,
        )}
      >
        <div className="min-w-0">
          {identity}
        </div>

        <div className="mt-7 min-w-0">
          {operations}
        </div>

        <div className="mt-7 min-w-0">
          {metrics}
        </div>
      </div>
    </header>
  );
}
EOF

cat > \
apps/lumina-builder/src/components/design-system/lumina/executive/ribbon/index.ts <<'EOF'
export {
  LuminaExecutiveRibbon,
} from "./LuminaExecutiveRibbon";

export type {
  LuminaExecutiveRibbonProps,
} from "./LuminaExecutiveRibbon";
EOF

python3 - <<'PY'
from pathlib import Path

path = Path(
    "apps/lumina-builder/src/components/design-system/lumina/executive/index.ts"
)

text = path.read_text()
line = 'export * from "./ribbon";\n'

if line not in text:
    text = text.rstrip() + "\n" + line

path.write_text(text)
PY

cat > \
apps/lumina-builder/src/components/workspaces/knowledge-v3/layout/ExecutiveRibbon.tsx <<'EOF'
import {
  LuminaExecutiveRibbon,
} from "@/components/design-system/lumina";

import {
  ExecutiveIdentity,
} from "./ExecutiveIdentity";
import {
  ExecutiveMetrics,
} from "./ExecutiveMetrics";
import {
  ExecutiveOperationsDeck,
} from "./ExecutiveOperationsDeck";

export function ExecutiveRibbon() {
  return (
    <LuminaExecutiveRibbon
      identity={
        <ExecutiveIdentity />
      }
      operations={
        <ExecutiveOperationsDeck />
      }
      metrics={
        <ExecutiveMetrics />
      }
    />
  );
}
EOF

echo
echo "===== EXECUTIVE RIBBON ====="
sed -n '1,280p' \
  apps/lumina-builder/src/components/design-system/lumina/executive/ribbon/LuminaExecutiveRibbon.tsx

echo
echo "===== KNOWLEDGE ADAPTER ====="
cat \
  apps/lumina-builder/src/components/workspaces/knowledge-v3/layout/ExecutiveRibbon.tsx

echo
echo "===== DIFF CHECK ====="
git diff --check

echo
echo "===== BUILD ====="
npm run build

echo
echo "===== KNOWLEDGE CHANGE SCOPE ====="
git diff --name-only -- \
  apps/lumina-builder/src/components/workspaces/knowledge

echo
echo "===== WORKTREE ====="
git status --short
Expected Knowledge change scope:
apps/lumina-builder/src/components/workspaces/knowledge-v3/layout/ExecutiveRibbon.tsx
Expected worktree also contains the new executive/ribbon files and the protected unstaged RuntimeHeader.tsx. Do not commit until the full executive ribbon is visually unchanged.
